  const thumbPromises=new Map();
  function applyFontScale(value){const number=Number(value),scale=Number.isFinite(number)?Math.max(1,Math.min(1.5,number)):1.2;document.documentElement.style.setProperty('--font-scale',String(scale));return scale;}
  function toast(message,error=false){const node=document.createElement('div');node.className='toast'+(error?' error':'');node.textContent=m(message);$('toast-root').append(node);setTimeout(()=>node.remove(),error?7000:3800);}
  async function run(fn){try{return await fn();}catch(error){toast(error.message||String(error),true);console.error(error);return null;}}
  function thumbnail(photo,size=700){const key=photo.id+':'+size;if(thumbPromises.has(key))return thumbPromises.get(key);const promise=new Promise((resolve,reject)=>{thumbQueue.push({photo,size,resolve,reject});pumpThumbs();});thumbPromises.set(key,promise);promise.catch(()=>thumbPromises.delete(key));return promise;}
