  function updatedPhotos(result){const arr=Array.isArray(result)?result:result?.photos||result?.updated||[];if(!Array.isArray(arr))return;const updates=new Map(arr.map(p=>[p.id,p]));state.photos=state.photos.map(p=>updates.has(p.id)?{...p,...updates.get(p.id)}:p);}
