  function setView(view){$('main-scroll').scrollTo({top:0,behavior:'instant'});state.view=view;state.visible=120;$('sync-sd-button').hidden=view!=='favorites';$('navigation').querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('breadcrumb-view').textContent=names[view];$('view-title').firstChild.textContent=names[view]+' ';$('view-description').textContent=descriptions[view];$('hero').hidden=view!=='all';$('section-eyebrow').textContent=({all:'YOUR PHOTO JOURNEY',favorites:'MOMENTS CLOSE TO THE HEART',colors:'A JOURNEY THROUGH COLOR',similar:'FIND YOUR VISUAL ECHO',collage:'MAKE YOUR OWN STORY'})[view];renderMode();render();}
  function renderMode(){const panel=$('mode-panel');panel.hidden=['all','favorites'].includes(state.view);if(state.view==='colors'){panel.innerHTML=`<div><h3>一抹颜色，一段回忆</h3><p>在当前日期范围内分析色彩，轻点色块即可筛选。不移动原照片。</p><div class="swatches">${Object.entries(colors).map(([k,v])=>`<button class="swatch-button ${$('color-filter').value===k?'active':''}" data-color="${k}" style="background:${v[1]}" aria-label="${v[0]}" title="${v[0]}"></button>`).join('')}</div></div><button class="button primary" id="analyze-colors">✧ 分析当前照片色彩</button>`;panel.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{$('color-filter').value=$('color-filter').value===b.dataset.color?'':b.dataset.color;renderMode();render();});$('analyze-colors').onclick=()=>run(async()=>{const ids=getFiltered().map(p=>p.id);if(!ids.length)return toast('当前筛选中没有照片');showProgress('colors','正在寻找照片里的色彩',ids.length);try{updatedPhotos(await api.analyzeColors({ids}));render();toast(progressCanceled?'已取消分析，已完成的色彩结果保留':'色彩分析完成，可以按色系浏览了');}finally{hideProgress();}});
    }else if(state.view==='similar'){panel.innerHTML=`<div><h3>用像素寻找相似的光影</h3><p>选一张参考照片，再选择搜索目录。按需计算，不建立向量库。</p><div class="light-label" style="margin-top:8px" id="similar-reference" ${state.referenceId?'data-i18n-ignore':''}>${state.referenceId?esc(state.photos.find(p=>p.id===state.referenceId)?.name||''):'参考照片：请多选一张照片，或打开照片详情设置'}</div></div><div class="mode-actions"><select id="similar-grid" title="像素池化颗粒度"><option value="8">8 × 8 · 构图轮廓</option><option value="16" selected>16 × 16 · 均衡</option><option value="32">32 × 32 · 细节</option><option value="64">64 × 64 · 更细节</option></select><button class="button quiet" id="similar-directory">选择搜索目录</button><button class="button primary" id="start-similar">◎ 开始搜索</button></div>`;$('similar-directory').onclick=()=>run(async()=>{const p=await api.chooseFolder();if(p){state.similarDirectory=p;$('similar-directory').setAttribute('data-i18n-ignore','');$('similar-directory').textContent=p.split('/').filter(Boolean).pop()||p;}});$('start-similar').onclick=()=>run(searchSimilar);
    }else if(state.view==='collage'){panel.innerHTML='<div><h3>让回忆，在同一张画面里相遇</h3><p>勾选照片，使用长图、四宫格、九宫格或海报模板。可直接拖动图片调整顺序。</p></div><button class="button primary" id="open-collage">▧ 打开拼图工作台</button>';$('open-collage').onclick=()=>run(openCollage);}}
  async function searchSimilar(){const referenceId=state.selected.size===1?[...state.selected][0]:state.referenceId;if(!referenceId)return toast('请先选择一张参考照片');if(!state.similarDirectory){const dir=await api.chooseFolder();if(!dir)return;state.similarDirectory=dir;}state.referenceId=referenceId;const grid=Number($('similar-grid').value);showProgress('similarity','正在按像素池化搜索相似照片',state.photos.length,Math.ceil(state.photos.length*(grid/16)*.06));try{const result=await api.similar({referenceId,directory:state.similarDirectory,grid,limit:500});if(progressCanceled)return;const list=Array.isArray(result)?result:result?.photos||result?.results||[];state.similar=list.map(p=>p.photo?{...p.photo,similarity:p.score??p.similarity}:p.id?{...state.photos.find(q=>q.id===p.id),...p,similarity:p.similarity??p.score}:p).filter(p=>p?.id);for(const p of state.similar)if(!state.photos.some(q=>q.id===p.id))state.photos.push(p);state.selected.clear();renderMode();render();toast(t('找到 {count} 张相似照片',{count:state.similar.length}));}finally{hideProgress();}}
  function showProgress(kind,title,total=0,eta=0){progressCanceled=false;state.progressKind=kind;state.progressTitle=title;$('progress-section').hidden=false;$('progress-title').textContent=m(title);$('cancel-progress').hidden=kind==='scan';$('cancel-progress').disabled=false;onProgress({kind,done:0,total,etaSeconds:eta});}
  function hideProgress(){state.progressKind='';$('progress-section').hidden=true;}
  function onProgress(p){if(p?.kind==='scan'&&state.scanning&&state.scanStreaming&&Array.isArray(p.photos)){state.photos=p.photos;populateFilters();render();}if(!p||p.kind!==state.progressKind)return;state.lastProgress=p;const total=p.total||0,done=p.done||0;$('progress-bar').style.width=total?Math.min(100,done/total*100)+'%':'5%';const phase=state.progressKind==='import'?({discovering:'正在查找来源照片',preparing:'正在查找来源照片',metadata:'正在读取拍摄信息',copying:'正在复制照片',indexing:'正在建立主题索引',indexed:'主题索引已建立',done:'正在完成导入'}[p.phase]||state.progressTitle):state.progressTitle;$('progress-title').textContent=m(phase||'正在处理照片');$('cancel-progress').hidden=state.progressKind==='scan'||p.phase==='indexing'||p.phase==='indexed';$('progress-text').textContent=`${done.toLocaleString()}${total?' / '+total.toLocaleString():''}${p.etaSeconds>0?' · '+(p.etaSeconds>60?t('预计剩余 {count} 分钟',{count:Math.ceil(p.etaSeconds/60)}):t('预计剩余 {count} 秒',{count:Math.ceil(p.etaSeconds)})):''}`;}
  function libraryRoots(settings=state.settings){return Array.isArray(settings.libraryRoots)?settings.libraryRoots.filter(Boolean):settings.libraryRoot?[settings.libraryRoot]:[];}
  function updateLibraryLabel(){const roots=state.roots;$('library-label').setAttribute('data-i18n-ignore','');$('library-label').textContent=roots.length>1?t('{count} 个照片目录',{count:roots.length}):roots[0]||state.root||t('选择照片文件夹开始');$('library-label').title=roots.join('\n')||state.root;}
  function selectTheme(theme,{persist=false}={}){const value=String(theme||'');if(value&&![...$('theme-filter').options].some(option=>option.value===value)){const option=document.createElement('option');option.value=value;option.textContent=value;option.setAttribute('data-i18n-ignore','');$('theme-filter').append(option);}$('theme-filter').value=value;if(persist){state.settings.defaultTheme=value;run(async()=>{state.settings=await api.saveSettings({defaultTheme:value});});}}
  function clearImportFilters(){for(const id of ['search','date-from','date-to','theme-filter','tag-filter','color-filter'])$(id).value='';state.selected.clear();state.selectionMode=false;state.similar=null;state.view='all';setView('all');}
  function trapFocus(node){node.addEventListener('keydown',event=>{if(event.key!=='Tab')return;const targets=[...node.querySelectorAll('button,input,select,textarea,a[href],[tabindex="0"]')].filter(el=>!el.disabled&&!el.hidden&&el.getClientRects().length);if(!targets.length)return;const first=targets[0],last=targets[targets.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}});}
  function modal({title,subtitle='',body='',footer='',large=false,onClose,titleIsData=false,subtitleIsData=false}){closeModal({replacement:true});const backdrop=document.createElement('div');backdrop.className='modal-backdrop';backdrop.innerHTML=`<section class="modal ${large?'large':''}" role="dialog" aria-modal="true" aria-label="${esc(titleIsData?title:m(title))}" ${titleIsData?'data-i18n-ignore-attrs="aria-label"':''}><div class="modal-header"><div><h3 ${titleIsData?'data-i18n-ignore':''}>${esc(titleIsData?title:m(title))}</h3>${subtitle?`<p ${subtitleIsData?'data-i18n-ignore':''}>${esc(subtitleIsData?subtitle:m(subtitle))}</p>`:''}</div><button class="modal-close" aria-label="关闭">×</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section>`;$('modal-root').append(backdrop);window.I18n?.apply(backdrop);backdrop.querySelector('.modal-close').onclick=()=>closeModal();backdrop.onclick=e=>{if(e.target===backdrop)closeModal();};trapFocus(backdrop);state.modalClose=onClose;setTimeout(()=>backdrop.querySelector('input:not([type=checkbox]),button')?.focus(),20);return backdrop;}
