  function syncEntry(value){return typeof value==='string'?value:value?.name||value?.path||value?.from||value?.message||JSON.stringify(value);}
  async function syncModal(){
    const favorites=state.photos.filter(p=>p.favorite).map(p=>p.id),selection=[...state.selected];
    if(!favorites.length&&!selection.length)return toast('请先收藏精品照片，或选择要保留的照片');
    const node=modal({title:'让 SD 卡，只留下心动的光影',subtitle:'保留所选照片对应的 JPEG 与 CR3，其他照片移入 SD 卡上的待删目录。',body:`<div class="field"><label for="sync-range">要保留哪些照片？</label><select id="sync-range"><option value="all" ${!favorites.length?'disabled':''}>${esc(t('全部精品收藏 · {count} 张',{count:favorites.length}))}</option><option value="selection" ${!selection.length?'disabled':''}>${esc(t('仅当前选择 · {count} 张',{count:selection.length}))}</option></select><small>默认保留全部精品。当前筛选条件不会缩减“全部精品”的范围。</small></div><div class="sync-warning">待删文件仍保存在 SD 卡上；相机不再显示这些照片，确认后手动删除待删目录才会释放空间。这里只整理 JPEG 与 CR3，视频及其他文件保留在原位，已有待删目录也会跳过。</div>`,footer:'<button class="button quiet" id="sync-range-cancel">取消</button><button class="button primary" id="sync-pick-folder">选择 SD 卡并预览</button>'});
    if(!favorites.length)node.querySelector('#sync-range').value='selection';node.querySelector('#sync-range-cancel').onclick=closeModal;
    node.querySelector('#sync-pick-folder').onclick=()=>run(async()=>{const ids=node.querySelector('#sync-range').value==='selection'?selection:favorites;if(!ids.length)return toast('这个范围内没有照片');const directory=await api.chooseFolder();if(!directory)return;node.querySelector('#sync-pick-folder').disabled=true;node.querySelector('#sync-pick-folder').textContent='正在核对 SD 卡…';try{const plan=await api.syncPreview({directory,ids});syncReview(plan);}catch(e){node.querySelector('#sync-pick-folder').disabled=false;node.querySelector('#sync-pick-folder').textContent='选择 SD 卡并预览';throw e;}});
  }
  function syncReview(plan){
    const keeps=plan.kept||[],moves=plan.moves||[],protectedFiles=plan.protected||[],unmatched=plan.unmatched||[],ambiguous=plan.ambiguous||[];
    const list=entries=>`<div class="sync-file-list">${entries.length?entries.map(v=>`<div data-i18n-ignore>${esc(syncEntry(v))}</div>`).join(''):'没有文件'}</div>`;
    const node=modal({title:'同步前，再看一眼这段光影',subtitle:plan.directory||t('所选 SD 卡'),subtitleIsData:true,large:true,body:`<div class="sync-counts"><span>${esc(t('保留 {count} 个文件',{count:Number(plan.keepCount??keeps.length)}))}</span><span>${esc(t('移入待删 {count} 个文件',{count:Number(plan.moveCount??moves.length)}))}</span><span>${esc(t('额外保护 {count} 个文件',{count:Number(plan.protectedCount??protectedFiles.length)}))}</span></div><div class="sync-warning">仅处理 JPEG 与 CR3，匹配时同时核对照片信息。日期不符或存在歧义的同名文件会受到保护。视频、其他文件和已有待删目录保留。待删文件仍保存在 SD 卡上；相机不再显示这些照片，确认后手动删除待删目录才会释放空间。</div><h4 class="sync-section-title">保留在 SD 卡中的 JPEG / CR3</h4>${list(keeps)}<h4 class="sync-section-title">将移入待删的文件 · 原位置 → 新位置</h4><div class="sync-file-list">${moves.length?moves.map(v=>`<div data-i18n-ignore>${esc(v.from||syncEntry(v))} → ${esc(v.to||t('待删'))}</div>`).join(''):'没有需要移动的文件'}</div>${protectedFiles.length?`<h4 class="sync-section-title">出于匹配安全额外保护的文件</h4>${list(protectedFiles)}`:''}${unmatched.length?`<h4 class="sync-section-title sync-error">${esc(t('未在 SD 卡中匹配的所选照片 · {count} 项',{count:unmatched.length}))}</h4>${list(unmatched)}`:''}${ambiguous.length?`<h4 class="sync-section-title sync-error">${esc(t('存在歧义，保留原位 · {count} 项',{count:ambiguous.length}))}</h4>${list(ambiguous)}`:''}<p class="help-text">请核对完整清单。确认后只移动文件，不永久删除照片。</p>`,footer:'<button class="button quiet" id="sync-review-cancel">返回相册</button><button class="button primary" id="sync-confirm">确认同步，仅移入待删</button>'});
    node.querySelector('#sync-review-cancel').onclick=closeModal;node.querySelector('#sync-confirm').onclick=()=>run(async()=>{node.querySelector('#sync-confirm').disabled=true;closeModal();showProgress('sync','正在保留精品，将其他照片移入待删',moves.length);try{const result=await api.syncFavorites({token:plan.token});const interrupted=result?.cancelled||result?.canceled;const count=result.movedCount??(Array.isArray(result.moved)?result.moved.length:Number(result.moved)||0),errors=result.errors||[];const done=modal({title:interrupted?'已停止同步，已移动的文件保留在待删':errors.length?'同步完成，部分文件需要检查':'SD 卡里的心动光影，已整理好',body:`<div class="sync-counts"><span>${esc(t('已移入待删 {count} 个文件',{count}))}</span><span>${esc(t('失败 {count} 个文件',{count:errors.length}))}</span></div><div class="sync-warning">待删文件仍保存在 SD 卡上；相机不再显示这些照片，确认后手动删除待删目录才会释放空间。JPEG 与 CR3 的移动清单随本次批次保留。</div>${result.batchDirectory?`<h4 class="sync-section-title">本次待删目录</h4><div class="sync-file-list" data-i18n-ignore>${esc(result.batchDirectory)}</div>`:''}${errors.length?`<h4 class="sync-section-title sync-error">未成功移动的文件</h4>${list(errors.map(e=>[e.path||e.from||'',e.message||syncEntry(e)].filter(Boolean).join(' · ')))}`:''}`,footer:`<button class="button quiet" id="sync-done-close">回到相册</button>${result.batchDirectory?'<button class="button primary" id="sync-reveal-batch">↗ 查看本次待删目录</button>':''}`});done.querySelector('#sync-done-close').onclick=closeModal;done.querySelector('#sync-reveal-batch')?.addEventListener('click',()=>run(async()=>{await api.revealDirectory({directory:result.batchDirectory});if(api.isDemo)toast('演示模式：正式软件会打开本次待删目录');}));}finally{hideProgress();}});
  }
  function bind(){for(const id of ['search','date-from','date-to','theme-filter','tag-filter','color-filter','sort-order'])$(id).addEventListener(id==='search'?'input':'change',()=>{state.visible=120;render();if(id==='theme-filter')selectTheme($(id).value,{persist:true});if(id==='color-filter'&&state.view==='colors')renderMode();});$('navigation').querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('choose-library').onclick=()=>run(chooseLibrary);$('empty-open').onclick=()=>run(chooseLibrary);$('refresh-button').onclick=()=>run(()=>state.busy?toast('请等待当前照片处理结束'):refresh());$('import-button').onclick=()=>run(importModal);$('settings-button').onclick=()=>run(settingsModal);$('sync-sd-button').onclick=()=>run(syncModal);$('reset-filters').onclick=()=>{for(const id of ['search','date-from','date-to','theme-filter','tag-filter','color-filter'])$(id).value='';selectTheme('',{persist:true});renderMode();render();};$('select-mode').onclick=()=>{state.selectionMode=!state.selectionMode;if(!state.selectionMode)state.selected.clear();renderSelection();};$('select-all').onclick=()=>{state.filtered.forEach(p=>state.selected.add(p.id));renderSelection();};$('clear-selection').onclick=()=>{state.selected.clear();state.selectionMode=false;renderSelection();};$('load-more').onclick=()=>{state.visible+=120;render();$('photo-grid').scrollIntoView({behavior:'smooth',block:'start'});};$('previous-page').onclick=()=>{state.visible=Math.max(120,state.visible-120);render();$('photo-grid').scrollIntoView({behavior:'smooth',block:'start'});};$('batch-tags').onclick=batchMeta;$('batch-favorite').onclick=()=>run(async()=>{await update([...state.selected],{favorite:true});toast('所选照片已收藏为精品');});$('batch-reveal').onclick=()=>run(copyModal);$('batch-collage').onclick=()=>run(openCollage);$('batch-gif').onclick=()=>run(openMotion);$('batch-delete').onclick=()=>run(async()=>{const ids=[...state.selected];const confirmed=api.isDemo?await confirmAction('把这些回忆移到废纸篓？',t('已选择 {count} 张照片。对应的 JPEG 和 CR3 都将一起移入系统废纸篓，可从系统废纸篓找回。',{count:ids.length}),'移到废纸篓',true):true;if(!confirmed)return;const result=await api.trash({ids,format:'both'});if(result?.canceled)return;state.selected.clear();await refresh();toast(`已将所选照片移到废纸篓${result?.failed?.length?'，部分文件未能移动，请检查':''}`);});$('cancel-progress').onclick=()=>run(async()=>{progressCanceled=true;$('cancel-progress').disabled=true;await api.cancel(state.progressKind);if(state.progressKind!=='import')hideProgress();toast('已请求取消');});document.addEventListener('keydown',event=>{const typing=['INPUT','TEXTAREA','SELECT'].includes(event.target.tagName);if(event.key==='Escape'&&state.languageChoosing){event.preventDefault();return;}if(event.key==='Escape'){if(state.confirmClose)state.confirmClose();else if($('modal-root').children.length)closeModal();else{state.selected.clear();state.selectionMode=false;renderSelection();}}if(!typing&&state.inspectorId&&(event.key==='ArrowLeft'||event.key==='ArrowRight'))inspectAdjacent(event.key==='ArrowLeft'?-1:1);if(!typing&&(event.metaKey||event.ctrlKey)&&event.key==='a'&&!$('modal-root').children.length){event.preventDefault();state.selectionMode=true;state.filtered.forEach(p=>state.selected.add(p.id));renderSelection();}});}
  document.addEventListener('i18n:change',()=>{if(!state.settingsReady)return;const emptyCopy=$('copy-directory');if(emptyCopy?.hasAttribute('data-i18n-empty-directory'))emptyCopy.textContent=t('尚未选择目标文件夹');const scroll=$('main-scroll').scrollTop,focused=document.activeElement,grid=$('similar-grid')?.value;populateFilters();$('breadcrumb-view').textContent=t(names[state.view]);$('view-title').firstChild.textContent=t(names[state.view])+' ';$('view-description').textContent=t(descriptions[state.view]);renderMode();if(grid&&$('similar-grid'))$('similar-grid').value=grid;if(state.similarDirectory&&$('similar-directory')){$('similar-directory').setAttribute('data-i18n-ignore','');$('similar-directory').textContent=state.similarDirectory.split('/').filter(Boolean).pop()||state.similarDirectory;}render();if(state.lastProgress&&state.progressKind)onProgress(state.lastProgress);window.I18n?.apply(document.body);$('main-scroll').scrollTo({top:scroll,behavior:'instant'});if(focused?.isConnected&&document.activeElement!==focused)focused.focus({preventScroll:true});});
  window.App={api,state,$,esc,applyFontScale,toast,run,modal,closeModal,confirmAction,thumbnail,refresh,update,render,parseTags,chooseLibrary,openSettings:settingsModal};
  bind();if(!api){$('empty-state').hidden=false;toast('请通过时光杂货店应用打开；浏览器预览可使用 ?demo=1。');return;}
  if(isDemo)$('demo-pill').hidden=false;
  api.onProgress?.(onProgress);
  run(async()=>{[state.settings]=await Promise.all([api.getSettings(),window.I18n.ready]);window.I18n.setLanguage(state.settings.language);state.settings=await window.LanguageUI.ensureChoice(state.settings);applyFontScale(state.settings.fontScale??1.2);window.__shiguangBootReady=true;state.roots=libraryRoots();const root=state.settings.libraryRoot||state.roots[0];if(root){await refresh(root);selectTheme(state.settings.defaultTheme||'');render();}else render();state.settingsReady=true;document.dispatchEvent(new Event('shiguang-ready'));window.Onboarding?.maybeStart();});
